### Example 

```moonbit
typealias S[T] = Array[T]

enum Nested[Z] {
  Cons(Z,Nested[S[Z]])
  Epsilon
}

fn Nested::length[A](self : Nested[A]) -> Int {
  match self {
    Cons(_,xs) => 1 + Nested::length(xs)
    Epsilon => 0
  }
}
test {
  let x0 = 1
  let x1 = [2,3,4]
  let x2 = [[5,6],[7],[8,9]]

  let acc0 = Cons(x2,Epsilon)
  let acc1 = Cons(x1,acc0)
  let acc2 = Cons(x0,acc1)
  println(acc2.length())
}
```

### A possible fix tip

use trait object to boxing all `Nested[A]` info `&VNested`


```moonbit
type S[T] 

enum Nested[Z] {
  Cons(Z,&VNested)
  Epsilon
}

trait VNested {
  length(Self) -> Int
}

impl[N] VNested for Nested[N] with length(self) {
  match self {
    Cons(_,xs) => 1 + VNested::length(xs)
    Epsilon => 0
  }
}

test {
  let x0 = 1
  let x1 = [2,3,4]
  let x2 = [[5,6],[7],[8,9]]

  let acc0 = Cons(x2,Epsilon)
  let acc1 = Cons(x1,acc0)
  let acc2 = Cons(x0,acc1)
  println(acc2.length())
}

```


