```moonbit
///|
enum MyList[A] {
  Nil
  Cons(A, &VMyList)
}
///|
trait VMyList : Show {}

impl[A : Show] Show for MyList[A] with output(self,logger) {
  match self {
    Nil => logger.write_string("nil")
    Cons(x,xs) => logger.write_string("Cons(\{x},\{xs})")
  }

}
///|
test {
  let x0 : MyList[Array[Array[Array[Int]]]] = Nil
  let x1 : MyList[Array[Array[Int]]] = Cons([[1, 2, 3], [1, 2, 3]], x0)
  let x2 : MyList[Array[Int]] = Cons([1,2,3],x1)
  let x3 : MyList[Int] = Cons(1,x2)
  inspect!(x3, content="Cons(1,Cons([1, 2, 3],Cons([[1, 2, 3], [1, 2, 3]],nil)))")
}

```

